        # Read eval_results.json for benchmarks
        f = os.path.join(d, 'eval_results.json')
        benchmarks = {}
        if os.path.exists(f):
            with open(f) as fh:
                data = json.load(fh)
            for bk, bv in data.get('benchmarks', {}).items():
                if isinstance(bv, dict) and 'accuracy' in bv:
                    benchmarks[bk] = round(bv['accuracy'], 4)
