                    bd = json.load(fh)
                bname = fn.replace('_results.json', '')
                if isinstance(bd, dict) and 'accuracy' in bd:
                    benchmarks[bname] = round(bd['accuracy'], 4)
        print(f'{name}: {benchmarks}  files={sorted(files)}')
